from content_helpers import code, output, choice, lesson, section, program

def sections():
    return [section("datafiles", "14. Контейнеры, файлы и ошибки", "Перейдите от последовательностей к словарям и надёжному вводу.", [
        lesson("maps", "std::map: ключ и значение", "Соберите частоты по именам.",
            "std::map<std::string,int> из <map> связывает уникальный ключ с числом. counts[word] возвращает значение по ключу и, если ключа ещё нет, вставляет его с начальным int=0. Поэтому ++counts[word] удобно считает частоты. Но чтение через [] тоже может изменить map; для проверки наличия без вставки используйте find и сравнение с end.\n\nПеребор for(const auto& entry : counts) читает пары: entry.first — ключ, entry.second — значение. По умолчанию map перебирает ключи по их порядку сравнения, для наших латинских слов — лексикографически. size() считает разные ключи, не общее число добавлений. Если нужен порядок поступления сообщений, map сама по себе его не сохраняет.",
            program('std::map<std::string, int> counts;\n++counts["Air"];\n++counts["Air"];\nstd::cout << counts.size() << " " << counts["Air"];', "iostream string map"),
            "Словарь не заменяет продуманную модель идентификаторов. Один и тот же ключ обозначает одну запись; повторная запись по нему меняет значение, а не создаёт вторую независимую сущность. Упорядоченный map и unordered_map имеют разные контракты и оценки; здесь рассматривается только map.",
            "[] может вставлять. Для чтения без изменения используйте find; при обходе ключ и значение находятся в first/second.", [
                code("frequency", "Сколько раз назван док?", 'Ввод: n (0…100), затем n латинских слов. Выведите число разных слов, затем для каждого ключа map строку «слово частота» с завершающим переносом. После числа разных слов тоже перенос.', 'int n = 0;\nstd::cin >> n;\nstd::map<std::string, int> counts;\nfor (int i = 0; i < n; ++i) {\n    std::string word; std::cin >> word; ++counts[word];\n}\nstd::cout << counts.size() << "\\n";\nfor (const auto& entry : counts) {\n    std::cout << entry.first << " " << entry.second << "\\n";\n}', [("4 Air Dock Air Bay", "3\nAir 2\nBay 1\nDock 1\n"), ("0", "0\n")], ["Число ключей — counts.size().", "Перебирайте пары const auto&, выводя first и second."], "map группирует одинаковые слова и выдаёт ключи в порядке сравнения.", headers="iostream string map", difficulty=2),
                code("lookup", "Запрос без вставки", 'Ввод: n (0…100), n слов, затем query. Подсчитайте частоты. Через find выведите частоту query или 0, затем размер словаря через пробел. Отсутствующий query не должен вставляться.', 'int n = 0;\nstd::cin >> n;\nstd::map<std::string, int> counts;\nfor (int i = 0; i < n; ++i) { std::string word; std::cin >> word; ++counts[word]; }\nstd::string query;\nstd::cin >> query;\nauto it = counts.find(query);\nint frequency = 0;\nif (it != counts.end()) { frequency = it->second; }\nstd::cout << frequency << " " << counts.size();', [("3 Air Dock Air Bay", "0 2"), ("3 Air Dock Air Air", "2 2")], ["operator[] для query добавил бы новый ключ.", "У итератора пары можно читать значение через it->second: это сокращение (*it).second."], "Стрелка -> обращается к члену объекта через указатель или подходящий итератор.", headers="iostream string map", difficulty=2),
                choice("insert", "Чтение, которое меняет", 'Что сделает counts["Missing"] у map<string,int>, если такого ключа не было?', ["Вставит ключ с нулевым int", "Всегда выбросит исключение", "Ничего не изменит и вернёт случайное число"], 0, ["Это особенность operator[] у map.", "Для запроса без вставки есть find."], "Одинаковый синтаксис [] у разных контейнеров не означает одинаковую семантику."),
                code("sumkeys", "Накопление по товарам", 'Ввод: n (0…100), затем n пар name amount; name — латинское слово, amount (0…100). Сложите amount по каждому имени в map и выведите общий итог всех значений словаря.', 'int n = 0;\nstd::cin >> n;\nstd::map<std::string, int> totals;\nfor (int i = 0; i < n; ++i) {\n    std::string name; int amount = 0;\n    std::cin >> name >> amount;\n    totals[name] += amount;\n}\nint sum = 0;\nfor (const auto& entry : totals) { sum += entry.second; }\nstd::cout << sum;', [("3 Food 2 Air 5 Food 3", "10"), ("0", "0")], ["Ключи объединяют записи одного товара.", "totals[name] += amount накапливает вместо простого присваивания."], "Сумма групп равна сумме исходных количеств, что даёт полезную дополнительную проверку.", headers="iostream string map")
            ], ["map", "ключи", "частоты"]),
        lesson("sets", "std::set и уникальность", "Выразите отсутствие дубликатов типом контейнера.",
            "std::set<int> из <set> хранит уникальные значения в порядке сравнения. insert(x) добавляет значение, если его ещё нет. size() считает разные элементы; count(x) для set возвращает 0 или 1. erase(x) удаляет ключ, если он есть; отсутствие ключа не создаёт ошибку само по себе.\n\nУ set нет доступа по порядковому индексу через []: это не vector. Перебирайте элементы range for. Чтобы сохранить порядок первого появления, нужен отдельный vector вместе с set для проверки, а не один set. Для задач принадлежности и уникальности set часто яснее ручного поиска повторов.",
            program('std::set<int> seen;\nseen.insert(7);\nseen.insert(2);\nseen.insert(7);\nstd::cout << seen.size();', "iostream set"),
            "Уникальность задаётся отношением сравнения контейнера. Для простых int это привычное равенство значений. Для пользовательских ключей правила сравнения требуют отдельного корректного контракта; не используйте случайный компаратор, который меняет смысл от вызова к вызову.",
            "set хранит множество, не исходную последовательность. Повторный insert не увеличивает размер.", [
                code("unique", "Разные номера шлюзов", 'Ввод: n (0…100), затем n номеров (0…99). Через set выведите число разных номеров.', 'int n = 0;\nstd::cin >> n;\nstd::set<int> seen;\nfor (int i = 0; i < n; ++i) { int x = 0; std::cin >> x; seen.insert(x); }\nstd::cout << seen.size();', [("5 7 2 7 9 2", "3"), ("0", "0")], ["Каждое значение можно вставлять без отдельного if.", "Повторы контейнер объединит автоматически."], "Выбор контейнера выражает требование уникальности напрямую.", headers="iostream set"),
                code("difference", "Уберите закрытый шлюз", 'Ввод: n (0…100), n номеров (0…99), затем closed. Добавьте номера в set, удалите closed и выведите оставшиеся по возрастанию, каждое с новой строки с завершающим переносом.', 'int n = 0;\nstd::cin >> n;\nstd::set<int> gates;\nfor (int i = 0; i < n; ++i) { int x = 0; std::cin >> x; gates.insert(x); }\nint closed = 0; std::cin >> closed;\ngates.erase(closed);\nfor (int x : gates) { std::cout << x << "\\n"; }', [("4 3 1 3 2 3", "1\n2\n"), ("0 7", "")], ["erase удаляет ключ независимо от числа его исходных повторов.", "Обход set уже упорядочен."], "Множество не хранит кратность исходных значений.", headers="iostream set"),
                choice("order", "Порядок сообщений", 'Сохранит ли set порядок первого появления номеров 7,2,7,9?', ["Нет, при обычном сравнении обход даст 2,7,9", "Да, обход даст 7,2,9", "Да, обход даст 7,2,7,9"], 0, ["set хранит упорядоченные уникальные значения.", "История вставок не является порядком обхода."], "Если нужен порядок появления, сочетайте отдельную последовательность с проверкой множества."),
                code("firstseen", "Первые появления", 'Ввод: n (0…100), n номеров (0…99). Выведите каждый различный номер один раз в порядке первого появления, через пробел. Используйте set для проверки и vector для порядка.', 'int n = 0;\nstd::cin >> n;\nstd::set<int> seen;\nstd::vector<int> order;\nfor (int i = 0; i < n; ++i) {\n    int x = 0; std::cin >> x;\n    if (seen.count(x) == 0) { seen.insert(x); order.push_back(x); }\n}\nbool first = true;\nfor (int x : order) {\n    if (!first) { std::cout << " "; }\n    first = false; std::cout << x;\n}', [("5 7 2 7 9 2", "7 2 9"), ("0", "")], ["Проверяйте seen до вставки.", "В order добавляйте только ещё не встречавшиеся номера."], "Две структуры отвечают за разные свойства: уникальность и порядок.", headers="iostream set vector", difficulty=3)
            ], ["set", "уникальность", "порядок"]),
        lesson("files", "Файловые потоки", "Обработайте отсутствие файла и проверьте запись.",
            "std::ifstream input(\"data.txt\") из <fstream> открывает файл для чтения относительно рабочей директории процесса. if(!input) проверяет, удалось ли открыть поток. Чтение input>>value похоже на cin, а while(input>>value) читает числа до неуспеха. Такой цикл не различает конец файла и ошибочный токен сам по себе; последующую проверку изучим далее.\n\nstd::ofstream output(\"journal.txt\") по умолчанию создаёт или обрезает файл. Для добавления используют std::ios::app. Перед записью проверьте открытие, после записи — состояние; при необходимости output.close() и ещё одна проверка обнаруживают отложенные ошибки. Поток закрывает ресурс через RAII.\n\nФайловые задачи выполняются только во внешней среде разработки. codelib показывает начальные и ожидаемые файлы, но не выполняет ваш код и не создаёт их сам.",
            program('std::ifstream input("data.txt");\nif (!input) { std::cout << "Missing"; return 0; }\nint value = 0;\nif (input >> value) { std::cout << value; }', "iostream fstream"),
            "Рабочая директория не обязана совпадать с папкой исходного файла или исполняемой программы. Файл может не открыться из-за пути, прав или отсутствия — не сводите любую ошибку к одной причине. Проверки относятся к реальному потоку, а не к предположению, что запись на диск всегда успешна.",
            "Проверьте открытие, чтение/запись и путь. Не используйте while(!eof()) как условие чтения очередного значения.", [
                code("read", "Первое число из файла", 'Файл data.txt, если существует, содержит одно целое от −100 до 100. Откройте его: при отсутствии выведите Missing, иначе прочитайте и выведите число. Ввод cin не используется.', 'std::ifstream input("data.txt");\nif (!input) { std::cout << "Missing"; return 0; }\nint value = 0;\nif (input >> value) { std::cout << value; }', [dict(input="", output="7", files={"data.txt":"7\n"}), dict(input="", output="Missing")], ["Файл ищется в рабочей директории.", "Проверьте if(!input) до чтения."], "Примеры отличаются наличием файла, а не строкой стандартного ввода.", headers="iostream fstream"),
                code("write", "Запишите короткий журнал", 'Ввод: n (−100…100). Создайте/перезапишите journal.txt строкой Value: <n> с переносом. Проверьте открытие и close: при успехе выведите Saved, при ошибке Error.', 'int n = 0;\nstd::cin >> n;\nstd::ofstream file("journal.txt");\nif (!file) { std::cout << "Error"; return 0; }\nfile << "Value: " << n << "\\n";\nfile.close();\nif (file) { std::cout << "Saved"; }\nelse { std::cout << "Error"; }', [dict(input="7", output="Saved", expectedFiles={"journal.txt":"Value: 7\n"}), dict(input="-2", output="Saved", files={"journal.txt":"old data"}, expectedFiles={"journal.txt":"Value: -2\n"})], ["Обычный ofstream заменяет прежнее содержимое.", "После close проверьте состояние file."], "Результат включает и стандартный вывод, и точное содержимое созданного файла.", headers="iostream fstream", difficulty=2),
                choice("eof", "Неправильный цикл", 'Почему while(!input.eof()) не подходит как общее условие «прочитать следующее число»?', ["EOF обычно обнаруживается после неудачной попытки чтения; проверять надо результат самого чтения", "eof всегда true сразу после открытия", "Файлы нельзя читать в цикле"], 0, ["Проверка до чтения не доказывает успех следующего чтения.", "Используйте while(input>>value)."], "Иначе легко обработать старое значение после неудачного чтения или не заметить неверный токен."),
                code("append", "Добавьте событие", 'Ввод: одно латинское слово event. Добавьте его и перенос в events.txt через ios::app. Проверьте поток после close, выведите Saved/Error. Старое содержимое должно сохраниться.', 'std::string event;\nstd::cin >> event;\nstd::ofstream file("events.txt", std::ios::app);\nif (!file) { std::cout << "Error"; return 0; }\nfile << event << "\\n";\nfile.close();\nif (file) { std::cout << "Saved"; }\nelse { std::cout << "Error"; }', [dict(input="Launch", output="Saved", files={"events.txt":"Ready\n"}, expectedFiles={"events.txt":"Ready\nLaunch\n"}), dict(input="Dock", output="Saved", expectedFiles={"events.txt":"Dock\n"})], ["Режим app отличается от обрезающего обычного открытия.", "Новая строка добавляется после существующего текста."], "В примерах прежнее содержимое уже заканчивается переносом; программа не добавляет отсутствующий разделитель за вас.", headers="iostream string fstream")
            ], ["fstream", "файлы", "ошибки записи"]),
        lesson("errors", "Ошибки ввода и исключения", "Не выдавайте частично прочитанные данные за успешный результат.",
            "if(!(cin>>value)) обнаруживает, что прочитать значение не удалось. Отрицательное число при успешном чтении — не ошибка формата, но может нарушать прикладное ограничение. Проверяйте эти уровни отдельно. Для одноразовой задачи можно завершиться с сообщением Invalid. Для интерактивного повторения потребуется очистить failbit через clear() и убрать неверный остаток; не зацикливайтесь на том же токене.\n\nvector.at(index) при неверном индексе выбрасывает std::out_of_range. Блок try { ... } catch(const std::out_of_range&) { ... } позволяет обработать именно эту ошибку; подключите <stdexcept>. Исключения — не замена всем обычным проверкам, а один из способов передачи ошибки. При обычной раскрутке стека владельцы RAII освобождают свои ресурсы.",
            program('std::vector<int> v = {4, 7};\ntry { std::cout << v.at(9); }\ncatch (const std::out_of_range&) { std::cout << "Invalid"; }', "iostream vector stdexcept"),
            "Отсутствие исключения не доказывает правильность: operator[] обычно вообще не делает такую проверку. И наоборот, успешное чтение числа не доказывает соответствие диапазону задачи. Система прогресса приложения также отделяет декодирование, проверку схемы и фактическую запись на диск.",
            "Разделяйте ошибку формата, неверный диапазон и ошибку операции. Не сообщайте об успехе до завершения проверки.", [
                code("input", "Надёжное единственное число", 'Ввод: один токен. Если его нельзя прочитать в int через >> либо полученное число вне 0…100, выведите Invalid; иначе удвоенное значение. При чтении токена 12x поток может успешно прочитать 12 — полного лексического анализа эта задача не требует.', 'int n = 0;\nif (!(std::cin >> n)) { std::cout << "Invalid"; return 0; }\nif (n < 0 || n > 100) { std::cout << "Invalid"; }\nelse { std::cout << 2 * n; }', [("abc", "Invalid"), ("-1", "Invalid"), ("7", "14"), ("12x", "24")], ["Сначала проверьте успех >>.", "После успешного чтения отдельно проверьте диапазон."], "Контракт явно отличает потоковый разбор числа от строгого разбора всего токена."),
                code("at", "Проверяемый доступ", 'Ввод: index (0…9). Вектор {4,7,9}. Прочитайте элемент через at, обработайте out_of_range и выведите Invalid при недопустимом индексе.', 'int index = 0;\nstd::cin >> index;\nstd::vector<int> v = {4, 7, 9};\ntry { std::cout << v.at(index); }\ncatch (const std::out_of_range&) { std::cout << "Invalid"; }', [("0", "4"), ("2", "9"), ("3", "Invalid")], ["Исключение выбрасывает at, не [].", "Catch должен обрабатывать std::out_of_range по const-ссылке."], "Ветвь ошибки не читает несуществующий элемент.", headers="iostream vector stdexcept"),
                choice("levels", "Число прочиталось", 'cin успешно прочитал −5, но приложению разрешены только 0…100. Что произошло?', ["Формат числа корректен, прикладной диапазон нарушен", "Успешное чтение доказывает допустимость для приложения", "Это обязательно ошибка компиляции"], 0, ["Поток знает синтаксис числа, не ваши бизнес-правила.", "Проверка диапазона — отдельная обязанность."], "Такое разделение полезно и для проверки файлов прогресса."),
                code("parse", "Сумма строки без мусора", 'Ввод: одна ASCII-строка длиной до 100. Разбейте её на токены через istringstream. Каждый токен должен полностью представлять целое от −100 до 100. Если есть неверный токен, выведите Invalid, иначе сумму. Пустая строка даёт 0. Проверяйте успех чтения числа и отсутствие лишнего символа в отдельном потоке токена.', 'std::string line;\nstd::getline(std::cin, line);\nstd::istringstream input(line);\nstd::string token;\nint sum = 0;\nbool valid = true;\nwhile (input >> token) {\n    std::istringstream one(token);\n    int value = 0; char extra = 0;\n    if (!(one >> value) || (one >> extra) || value < -100 || value > 100) {\n        valid = false; break;\n    }\n    sum += value;\n}\nif (valid) { std::cout << sum; }\nelse { std::cout << "Invalid"; }', [("1 2 -3\n", "0"), ("1 x 3\n", "Invalid"), ("12x\n", "Invalid"), ("999999999999999999999999\n", "Invalid"), ("101\n", "Invalid"), ("\n", "0")], ["istringstream из <sstream> даёт строке интерфейс потока.", "Для каждого токена сначала прочитайте int, затем попробуйте прочитать лишний char. Успех второго чтения означает мусор."], "Одна проверка eof после неуспеха недостаточна: переполнение при чтении числа тоже может совпасть с концом входа. Отдельные проверки токена не принимают 12x и слишком большое число.", headers="iostream string sstream", difficulty=3)
            ], ["ошибки ввода", "исключения", "sstream"])
    ])]
